  3053	decodeFields(CtxJson *ctx, ParseCtx *parseCtx, DecodeEntry *entries,
  3054	             size_t entryCount, const UA_DataType *type) {
  3055	    CHECK_TOKEN_BOUNDS;
  3056	    size_t objectCount = (size_t)(parseCtx->tokenArray[parseCtx->index].size);
  3057	    status ret = UA_STATUSCODE_GOOD;
