  3062	                                       ctx, parseCtx, true); /*ENCODE DIRECT*/
  3063	        }
  3064	    } else if(entryCount == 0) {
  3065	        return UA_STATUSCODE_BADDECODINGERROR;
  3066	    }
  3067	
  3068	    parseCtx->index++; /*go to first key*/
  3069	    CHECK_TOKEN_BOUNDS;
