  3071	    for (size_t currentObjectCount = 0; currentObjectCount < objectCount &&
  3072	             parseCtx->index < parseCtx->tokenCount; currentObjectCount++) {
  3073	
  3074	        /* start searching at the index of currentObjectCount */
  3075	        for (size_t i = currentObjectCount; i < entryCount + currentObjectCount; i++) {
  3076	            /* Search for KEY, if found outer loop will be one less. Best case
  3077	             * is objectCount if in order! */
  3078	            size_t index = i % entryCount;
  3079	            
  3080	            CHECK_TOKEN_BOUNDS;
  3081	            if(jsoneq((char*) ctx->pos, &parseCtx->tokenArray[parseCtx->index], 
